import java.util.Scanner;
public class BmiCalculator2 {
	public static void main(String[] args) {
		//Khatwa 1: Istilam al-wazn wal-irtifa' min al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil al-wazn bil-pounds:");
		double weight = scan.nextDouble();
		System.out.println("Adkhil al-irtifa' bil-inches:");
		double height = scan.nextDouble();
		scan.close();
		//Khatwa 2: Hisaab al-BMI
		double bmi = weight / Math.pow(height, 2) * 703;	
		//Khatwa 3: Taqreeb al-BMI ila aqrab 'adad sahih
		bmi = Math.round(bmi);
		//Khatwa 4: Isqaat al-juz' al-kasri min al-BMI
		int resultBmi = (int) bmi;
		//Khatwa 5: Taba'a al-natayij
		System.out.println("Al-BMI al-muqarrab ila aqrab 'adad sahih huwa: " + resultBmi);
	}
}
